import type {LicenseHolder} from './types'
import {CustomerIdProvider} from './CustomerIdContext'
import {FormControl, Link, Pagination, Select, TextInput} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {useCallback, useEffect, useMemo, useState} from 'react'
import {updateSearchParams as updateBrowserSearchParams} from '@github-ui/history'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {ListView} from '@github-ui/list-view'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {ListItemLeadingContent} from '@github-ui/list-view/ListItemLeadingContent'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListItem} from '@github-ui/list-view/ListItem'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import {AlertIcon, ProjectRoadmapIcon, SearchIcon, XCircleFillIcon} from '@primer/octicons-react'
import {LicenseDetails} from './LicenseDetails'
import {getSignificanceBasedPrecision, human} from '@github-ui/formatters'
import {useSearchParams} from '@github-ui/use-navigate'
import {ProductProvider} from './ProductContext'
import styles from './LicensifyLicenses.module.css'

export interface LicensifyLicensesProps {
  customerId: string
  product: string
  products?: string[]
  licenseStatuses: string[]
  enablementReasons: string[]
}

const LoadingState = {
  Loading: 'Loading',
  Done: 'Done',
  Error: 'Error',
} as const

type LoadingState = (typeof LoadingState)[keyof typeof LoadingState]

const PAGE_SIZE = 25
const DEFAULT_LICENSE_STATUS = 'LICENSE_STATUS_UNSPECIFIED'
const DEFAULT_ENABLEMENT_REASON = 'ENABLEMENT_REASON_UNSPECIFIED'
const DEFAULT_PAGE = 1

function normalizeLicenseeId(licenseeId: string | number | undefined) {
  return licenseeId === undefined ? undefined : String(licenseeId)
}

function getInitialPage(page: string | null) {
  if (!page) return DEFAULT_PAGE

  const parsedPage = Number(page)

  return Number.isInteger(parsedPage) && parsedPage > 0 ? parsedPage : DEFAULT_PAGE
}

function updateParam(searchParams: URLSearchParams, key: string, value?: string) {
  if (value) {
    searchParams.set(key, value)
  } else {
    searchParams.delete(key)
  }
}

function getInitialFilterValue(searchParamValue: string | null, validOptions: string[], fallbackValue: string) {
  return searchParamValue && validOptions.includes(searchParamValue) ? searchParamValue : fallbackValue
}

function getInitialProduct(searchParams: URLSearchParams, product: string, products?: string[]) {
  const searchProduct = searchParams.get('product')

  if (products && products.length > 0) {
    if (searchProduct && products.includes(searchProduct)) {
      return searchProduct
    }

    if (products.includes(product)) {
      return product
    }

    return products[0] || product
  }

  return searchProduct || product
}

export function LicensifyLicenses({
  customerId,
  product,
  products,
  licenseStatuses,
  enablementReasons,
}: LicensifyLicensesProps) {
  const [params] = useSearchParams()
  const [currentSearchParams, setCurrentSearchParams] = useState(() => new URLSearchParams(params))
  const [state, setState] = useState<LoadingState>(LoadingState.Loading)
  const [licenseHolders, setLicenseHolders] = useState<LicenseHolder[]>([])
  const [status, setStatus] = useState(() =>
    getInitialFilterValue(params.get('license_status'), licenseStatuses, DEFAULT_LICENSE_STATUS),
  )
  const [enablementReason, setEnablementReason] = useState(() =>
    getInitialFilterValue(params.get('enablement_reason'), enablementReasons, DEFAULT_ENABLEMENT_REASON),
  )

  const [selectedProduct, setSelectedProduct] = useState(() => getInitialProduct(params, product, products))

  const updateQueryParam = useCallback((key: string, value?: string) => {
    setCurrentSearchParams(previousParams => {
      const nextParams = new URLSearchParams(previousParams)
      updateParam(nextParams, key, value)

      if (nextParams.toString() !== previousParams.toString()) {
        updateBrowserSearchParams(nextParams)
        return nextParams
      }

      return previousParams
    })
  }, [])

  const handleProductChange = useCallback(
    (nextProduct: string) => {
      setSelectedProduct(nextProduct)
      updateQueryParam('product', nextProduct)
    },
    [updateQueryParam],
  )

  const handleStatusChange = useCallback(
    (nextStatus: string) => {
      setStatus(nextStatus)
      updateQueryParam('license_status', nextStatus === DEFAULT_LICENSE_STATUS ? undefined : nextStatus)
    },
    [updateQueryParam],
  )

  const handleEnablementReasonChange = useCallback(
    (nextEnablementReason: string) => {
      setEnablementReason(nextEnablementReason)
      updateQueryParam(
        'enablement_reason',
        nextEnablementReason === DEFAULT_ENABLEMENT_REASON ? undefined : nextEnablementReason,
      )
    },
    [updateQueryParam],
  )

  const activeProduct = selectedProduct
  const fetchLicenses = useCallback(async () => {
    setState(LoadingState.Loading)
    const response = await verifiedFetchJSON(
      `/stafftools/customers/${customerId}/licensify_licenses?license_status=${status}&product=${activeProduct}&enablement_reason=${enablementReason}`,
    )

    if (response.ok) {
      const data = await response.json()
      setState(LoadingState.Done)
      data.sort((a: LicenseHolder, b: LicenseHolder) => a.display_name.localeCompare(b.display_name))
      setLicenseHolders(data || [])
    } else {
      setState(LoadingState.Error)
    }
  }, [customerId, activeProduct, status, enablementReason])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    fetchLicenses()
  }, [fetchLicenses])

  return (
    <div className="tmp-my-3">
      <h3>{activeProduct.toUpperCase()} Licenses</h3>
      <div className={styles.dropdownContainer}>
        {products && products.length > 0 && (
          <FormControl className={styles.formControl}>
            <FormControl.Label>Product</FormControl.Label>
            <Select value={selectedProduct} onChange={e => handleProductChange(e.target.value)}>
              {products.map(p => (
                <Select.Option key={p} value={p}>
                  {p.toUpperCase()}
                </Select.Option>
              ))}
            </Select>
          </FormControl>
        )}
        <FormControl className={styles.formControl}>
          {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
          <FormControl.Label>License Status</FormControl.Label>
          <Select value={status} onChange={e => handleStatusChange(e.target.value)}>
            {licenseStatuses.map(s => (
              <Select.Option key={s} value={s}>
                {s}
              </Select.Option>
            ))}
          </Select>
        </FormControl>
        {enablementReasons?.length > 0 && (
          <FormControl className={styles.formControl}>
            {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
            <FormControl.Label>Enablement Reason</FormControl.Label>
            <Select value={enablementReason} onChange={e => handleEnablementReasonChange(e.target.value)}>
              {enablementReasons.map(s => (
                <Select.Option key={s} value={s}>
                  {s}
                </Select.Option>
              ))}
            </Select>
          </FormControl>
        )}
      </div>
      <CustomerIdProvider customerId={customerId}>
        <ProductProvider product={activeProduct}>
          <LicensesContent
            state={state}
            licenseHolders={licenseHolders}
            reloadLicenses={fetchLicenses}
            initialLicenseeId={currentSearchParams.get('licensee_id') ?? undefined}
            initialPage={getInitialPage(currentSearchParams.get('page'))}
            onLicenseeIdChange={licenseeId => updateQueryParam('licensee_id', licenseeId)}
            onPageChange={page => updateQueryParam('page', page > DEFAULT_PAGE ? String(page) : undefined)}
          />
        </ProductProvider>
      </CustomerIdProvider>
    </div>
  )
}

interface LicensesContentProps {
  state: LoadingState
  licenseHolders: LicenseHolder[]
  reloadLicenses: () => void
  initialLicenseeId?: string
  initialPage: number
  onLicenseeIdChange: (licenseeId?: string) => void
  onPageChange: (page: number) => void
}

function LicensesContent({
  state,
  licenseHolders,
  reloadLicenses,
  initialLicenseeId,
  initialPage,
  onLicenseeIdChange,
  onPageChange,
}: LicensesContentProps) {
  if (state === LoadingState.Loading) {
    return (
      <div className="border rounded-2">
        <div className="d-flex tmp-p-3 border-bottom">
          <LoadingSkeleton className="mr-2" variant="pill" height="sm" width="sm" />
          <LoadingSkeleton variant="text" height="sm" width="100%" />
        </div>
        <div className="d-flex tmp-p-3 border-bottom">
          <LoadingSkeleton className="mr-2" variant="pill" height="sm" width="sm" />
          <LoadingSkeleton variant="text" height="sm" width="100%" />
        </div>
      </div>
    )
  }
  if (state === LoadingState.Error) {
    return (
      <Blankslate border>
        <Blankslate.Visual>
          <AlertIcon size="medium" />
        </Blankslate.Visual>
        <Blankslate.Heading>There was an error loading licenses</Blankslate.Heading>
        <Link onClick={reloadLicenses}>Try again</Link>
      </Blankslate>
    )
  }
  return (
    <LicenseHolderList
      licenseHolders={licenseHolders}
      initialLicenseeId={initialLicenseeId}
      initialPage={initialPage}
      onLicenseeIdChange={onLicenseeIdChange}
      onPageChange={onPageChange}
    />
  )
}

interface LicenseHolderListProps {
  licenseHolders: LicenseHolder[]
  initialLicenseeId?: string
  initialPage: number
  onLicenseeIdChange: (licenseeId?: string) => void
  onPageChange: (page: number) => void
}

function getPageForLicensee(licenseHolders: LicenseHolder[], licenseeId?: string) {
  if (!licenseeId) return 1

  const selectedIndex = licenseHolders.findIndex(licenseHolder => normalizeLicenseeId(licenseHolder.id) === licenseeId)

  return selectedIndex >= 0 ? Math.floor(selectedIndex / PAGE_SIZE) + 1 : 1
}

function getDisplayLicensesCount(count: number): string {
  const displayCount = human(count, {
    precision: getSignificanceBasedPrecision(count),
    suffix: false,
  })

  return `${displayCount} ${count === 1 ? 'license' : 'licenses'}`
}

function NoLicenses() {
  return (
    <Blankslate>
      <Blankslate.Visual>
        <ProjectRoadmapIcon size="medium" />
      </Blankslate.Visual>
      <Blankslate.Heading>No licenses found</Blankslate.Heading>
      <Blankslate.Description>Try adjusting your filter criteria</Blankslate.Description>
    </Blankslate>
  )
}

function LicenseHolderList({
  licenseHolders,
  initialLicenseeId,
  initialPage,
  onLicenseeIdChange,
  onPageChange,
}: LicenseHolderListProps) {
  const [filterValue, setFilterValue] = useState('')
  const [requestedPage, setRequestedPage] = useState(() =>
    initialLicenseeId ? getPageForLicensee(licenseHolders, initialLicenseeId) : initialPage,
  )

  const filteredLicenseHolders = useMemo(() => {
    if (!filterValue) {
      return licenseHolders
    }

    return licenseHolders.filter(
      licenseHolder =>
        licenseHolder.display_name.toLowerCase().includes(filterValue.toLowerCase()) ||
        licenseHolder.id.toString() === filterValue,
    )
  }, [licenseHolders, filterValue])

  const effectiveSelectedLicenseeId = useMemo(() => {
    if (!initialLicenseeId) return undefined

    return filteredLicenseHolders.some(licenseHolder => normalizeLicenseeId(licenseHolder.id) === initialLicenseeId)
      ? initialLicenseeId
      : undefined
  }, [filteredLicenseHolders, initialLicenseeId])

  useEffect(() => {
    if (initialLicenseeId && !effectiveSelectedLicenseeId) {
      onLicenseeIdChange(undefined)
    }
  }, [effectiveSelectedLicenseeId, initialLicenseeId, onLicenseeIdChange])

  const handleOpenDetails = useCallback(
    (licenseeId: string) => {
      const normalizedLicenseeId = normalizeLicenseeId(licenseeId)
      onLicenseeIdChange(normalizedLicenseeId)
    },
    [onLicenseeIdChange],
  )

  const handleCloseDetails = useCallback(() => {
    onLicenseeIdChange(undefined)
  }, [onLicenseeIdChange])

  const licenseCount = filteredLicenseHolders.length
  const pageCount = Math.max(Math.ceil(licenseCount / PAGE_SIZE), DEFAULT_PAGE)
  const currentPage = effectiveSelectedLicenseeId
    ? getPageForLicensee(filteredLicenseHolders, effectiveSelectedLicenseeId)
    : Math.min(requestedPage, pageCount)
  const handlePaginationChange = useCallback((e: React.MouseEvent, page: number) => {
    setRequestedPage(page)
    e.preventDefault()
  }, [])

  useEffect(() => {
    onPageChange(currentPage)
  }, [currentPage, onPageChange])

  const licensesOnPage = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE
    const end = Math.min(currentPage * PAGE_SIZE, licenseCount)
    return filteredLicenseHolders.slice(start, end)
  }, [currentPage, filteredLicenseHolders, licenseCount])

  return (
    <>
      <TextInput
        aria-label="Filter by ID or display name"
        leadingVisual={SearchIcon}
        block
        placeholder="Filter by ID or display name"
        className="tmp-mb-3"
        value={filterValue}
        onChange={e => setFilterValue(e.target.value)}
        trailingAction={
          <TextInput.Action
            onClick={() => {
              setFilterValue('')
            }}
            icon={XCircleFillIcon}
            aria-label="Clear input"
            className="fgColor-muted"
          />
        }
      />
      <div className="border rounded-2">
        {licenseCount === 0 ? (
          <NoLicenses />
        ) : (
          <ListView
            title="List of license holders"
            totalCount={licenseCount}
            metadata={<ListViewMetadata title={getDisplayLicensesCount(licenseCount)} />}
            singularUnits="license"
            pluralUnits="licenses"
          >
            {licensesOnPage.map(licenseHolder => (
              <LicenseHolderItem
                key={`${licenseHolder.type}-${normalizeLicenseeId(licenseHolder.id)}`}
                licenseHolder={licenseHolder}
                isDialogOpen={effectiveSelectedLicenseeId === normalizeLicenseeId(licenseHolder.id)}
                onOpenDetails={() => handleOpenDetails(normalizeLicenseeId(licenseHolder.id) ?? '')}
                onCloseDetails={handleCloseDetails}
              />
            ))}
          </ListView>
        )}
      </div>
      {pageCount > 1 && (
        <Pagination pageCount={pageCount} currentPage={currentPage} onPageChange={handlePaginationChange} />
      )}
    </>
  )
}

interface LicenseHolderItemProps {
  licenseHolder: LicenseHolder
  isDialogOpen: boolean
  onOpenDetails: () => void
  onCloseDetails: () => void
}

function LicenseHolderItem({licenseHolder, isDialogOpen, onOpenDetails, onCloseDetails}: LicenseHolderItemProps) {
  return (
    <ListItem title={<ListItemTitle value={licenseHolder.display_name} onClick={onOpenDetails} />}>
      <ListItemLeadingContent>
        {licenseHolder.avatar_url ? (
          <GitHubAvatar className="mr-2 flex-self-center" src={licenseHolder.avatar_url} />
        ) : null}
      </ListItemLeadingContent>
      {isDialogOpen && <LicenseDetails licenseHolder={licenseHolder} onClose={onCloseDetails} />}
    </ListItem>
  )
}
